import {WORLD,HOMES,SCENARIO} from './story.js';
import {NODE,RES,ROLES,missionCheck,isHidden} from './core.js';
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const home=p=>HOMES.find(h=>h.id===p.origin?.home);
export function originLabel(p){const h=home(p);return h?`${h.citizen} / ${p.origin.city}`:''}
export function campaignHTML(g){
 if(!g?.story)return `<div class="campaign-teaser"><span class="story-stamp">独立宣言<br><strong>DAY 01</strong></span><div><span class="eyebrow">A DIFFERENT STORY EVERY RUN</span><strong>昨日までの都県境は、今日から国境。</strong><p>${g?'この保存データは旧ルールの遠征です。新しい遠征から物語・任務・追跡が加わります。':'6つの物語 × ランダムな出身地・任務地点。正体を隠し、故郷へ帰れ。'}</p></div><span class="teaser-note">県外住民の帰国作戦<br>MISSION / PURSUIT / CO-OP</span></div>`;
 const s=SCENARIO[g.story.scenario],done=g.story.missions.filter(m=>m.done).length;
 return `<div class="campaign-active"><div class="campaign-name"><span class="eyebrow">INDEPENDENCE DAY / ${s.id.toUpperCase()}</span><strong>${s.title}</strong><small>${s.identity}</small></div><div class="origin-chips">${g.players.map(p=>`<span style="--home-color:${home(p)?.color}"><b>P${p.id+1} / ${esc(home(p)?.citizen||'県外住民')}</b><small>${esc(p.origin.city)}へ帰る</small></span>`).join('')}</div><button class="secondary" id="briefing-btn">作戦書 ${done}/3 ↗</button></div>`;
}
export function pursuitHTML(g){if(!g.pursuit)return'';const q=g.pursuit,s=SCENARIO[g.story.scenario];return `<div class="pursuit-card"><div class="pursuit-title"><span>! 追跡度</span><strong class="${q.heat>=7?'danger':''}">${q.heat}<small>/ 10</small></strong><button id="pursuit-info">対策 ↗</button></div><div class="heat-meter">${Array.from({length:10},(_,i)=>`<i class="${i<q.heat?'hot':''}"></i>`).join('')}</div><div class="pursuit-details"><span>追跡隊：${NODE[q.pos].name}${q.stunned?' / 陽動中':''}</span><span>拘束 ${q.strikes}/3</span></div><small>${q.heat>=7&&q.target?'広域捜索中。潜伏して追跡度を下げよう。':q.heat>=3&&q.target?'目撃情報を追跡中。徒歩なら新たな情報が残らない。':'追跡隊は手がかりを見失っている。'}</small></div>`}
export function missionBoardHTML(g){if(!g?.story)return'';const done=g.story.missions.filter(m=>m.done).length;return `<div class="section-heading"><div><span class="eyebrow">RETURN HOME / REQUIRED MISSIONS</span><h2>帰国には、3つの任務がいる。</h2></div><span class="mission-counter">${done} / 3 達成</span></div><div class="mission-grid">${g.story.missions.map((m,i)=>{const locked=m.requires?.some(id=>!g.story.missions.find(x=>x.id===id)?.done);return `<article class="mission-card ${m.done?'done':''}"><div class="mission-card-head"><span class="mission-letter">${m.done?'✓':String.fromCharCode(65+i)}</span><span>${m.done?'任務達成':locked?'先にA・Bを達成':'必須任務'}</span><span>${m.kind==='ally'?`${m.minPlayers}人集合`:'1人で実行可'}</span></div><h3>${m.title}</h3><p>${m.nodes.map(id=>NODE[id].name).join(' / ')}</p><div class="mission-cost">${Object.entries(m.need).map(([k,v])=>`${RES[k].label}${v}`).join('・')||'必要物資なし'} / 1行動</div><small>報酬：${Object.entries(m.reward).map(([k,v])=>`${RES[k].label}+${v}`).join('・')}${m.kind==='transmit'?'・追跡度−3':''}</small><button class="secondary" data-mission-locate="${m.id}">${m.done?'地点を確認':'任務地点へ'} ◎</button></article>`}).join('')}</div>`}
export function localMissionsHTML(g,node,control){if(!g.story)return'';return g.story.missions.filter(m=>m.nodes.includes(node)&&!m.done).map(m=>{const c=missionCheck(g,m.id);return `<div class="local-mission"><span>REQUIRED MISSION</span><strong>${m.title}</strong>${!c.ok?`<small>${esc(c.reasons.join(' / '))}</small>`:''}<button class="mission-action" data-perform-mission="${m.id}" ${!c.ok||!control||!g.ap?'disabled':''}>${m.verb} →</button></div>`}).join('')}
export function stealthHTML(g,control){if(!g.story)return'';const p=g.players[g.turn];return `<div class="stealth-actions"><button class="secondary" id="hide-btn" ${!control||!g.ap?'disabled':''}>◌ 潜伏 <small>追跡−3</small></button><button class="secondary" id="decoy-btn" ${!control||!g.ap||g.resources.signal<1?'disabled':''}>⌁ 陽動 <small>通信機1</small></button></div>${isHidden(g,p)?'<div class="concealed-note">◌ 潜伏中。次ラウンドまで発見を防ぐ。移動・探索・任務で解除。</div>':''}`}
export function briefingHTML(g){const s=SCENARIO[g.story.scenario];return `<span class="eyebrow">CLASSIFIED / RETURN HOME OPERATION</span><h2>${s.title}</h2><div class="independence-notice"><span>臨時放送 / 独立宣言</span><strong>「本日より、東京都は独立国家となる。」</strong></div><p>${WORLD.text}</p><h3>あなたたちの正体</h3><p>${s.identity}。${s.reveal}</p><div class="brief-origins">${g.players.map(p=>`<div><span style="color:${home(p)?.color}">P${p.id+1} ${esc(p.name)}</span><strong>${esc(originLabel(p))}</strong><small>${ROLES[p.role].name} / 正体がバレた手がかり：${home(p)?.tell}</small></div>`).join('')}</div><h3>追跡者：${s.pursuer}</h3><p>${s.tactic}</p><p>${WORLD.note}</p><h3>必須の帰国任務</h3><ol>${g.story.missions.map(m=>`<li>${m.done?'✓ ':''}<strong>${m.title}</strong><br>${m.nodes.map(id=>NODE[id].name).join(' または ')}${m.kind==='ally'?` / ${m.minPlayers}人が同じ地点に集合、食料2`:m.kind==='transmit'?' / A・Bの任務達成後、通信機1':' / 必要物資なし'}</li>`).join('')}</ol><p class="network-tip">3任務をすべて達成し、必要物資をそろえて、同じ出口に全員集合。追跡度は${s.trait==='gate'?4:6}以下が脱出条件です。任務は探索とは別の行動です。</p><button class="primary" id="briefing-close"><span>故郷への道を探す</span><span>↗</span></button>`}
export function pursuitInfoHTML(g){const s=SCENARIO[g.story.scenario];return `<span class="eyebrow">EVASION MANUAL</span><h2>国境警備の目をかわす。</h2><h3>${s.pursuer}</h3><p>${s.tactic}</p><ul><li>鉄道・探索は通常追跡度+1、任務は+2。追跡隊は最後に目撃された地点へ向かいます。</li><li>追跡度3以上で毎ラウンド1区間、7以上で2区間移動します。赤い「!」が現在地です。</li><li><strong>徒歩</strong>は新しい目撃情報を残しません。<strong>潜伏</strong>は1行動で追跡度−3。次のラウンドまでその人の発見を防ぎます。移動・探索・任務をすると解除されます。</li><li><strong>陽動</strong>は1行動と通信機1で、追跡度−4・追跡隊を1ラウンド足止め。出口に追跡隊がいる場合も、陽動中なら脱出できます。</li><li>追跡隊と同じ地点で発見されると錦糸町へ送還。体力−2・食料2没収・次の手番は1行動。チームで3度拘束されると失敗します。</li></ul><p>追跡度が高いままでは出国できません。最後に潜伏してから出口へ向かうか、陽動で隙を作りましょう。</p>`}
